INSERT INTO lessons (lesson_id,module_id,title,target_situation,order_index) VALUES
(401, 3, 'Báo lỗi phần mềm và mô tả cách tái hiện', 'Đồng nghiệp mô tả lỗi và cung cấp các bước giúp đội IT kiểm tra.', 3),
(402, 3, 'Họp cập nhật tiến độ dự án IT', 'Thành viên nhóm cập nhật công việc đã làm, trở ngại và bước tiếp theo.', 4),
(403, 3, 'Trao đổi bảo mật và chia sẻ dữ liệu', 'Nhân viên hỏi IT về quyền truy cập và cách gửi tài liệu an toàn.', 5),
(404, 3, 'Hướng dẫn đồng nghiệp dùng phần mềm mới', 'Người hướng dẫn giải thích thao tác cơ bản và kiểm tra người học đã hiểu.', 6),
(405, 4, 'Mô tả triệu chứng trong buổi khám', 'Người bệnh mô tả thời điểm xuất hiện triệu chứng cho bác sĩ.', 3),
(406, 4, 'Hỏi lịch xét nghiệm và hướng dẫn chuẩn bị', 'Người bệnh hỏi nhân viên xét nghiệm về lịch và hướng dẫn chính thức.', 4),
(407, 4, 'Xin hồ sơ y tế và xác nhận thông tin', 'Người bệnh hỏi cách nhận bản sao hồ sơ theo quy trình của cơ sở y tế.', 5),
(408, 4, 'Hỏi đường và tìm khoa trong bệnh viện', 'Khách hỏi quầy thông tin về vị trí khoa và khu chờ.', 6),
(409, 5, 'Mượn sách và hỏi quy định thư viện', 'Sinh viên tìm sách và hỏi thời hạn mượn hoặc gia hạn.', 3),
(410, 5, 'Phân chia nhiệm vụ trong dự án nhóm', 'Các thành viên nhóm thống nhất nhiệm vụ và lịch kiểm tra tiến độ.', 4),
(411, 5, 'Hỏi điều kiện và hồ sơ học bổng', 'Sinh viên hỏi nhân viên trường về tiêu chí và hạn nộp học bổng.', 5),
(412, 5, 'Nhận góp ý và cải thiện bài thuyết trình', 'Sinh viên trao đổi với giảng viên về điểm cần cải thiện.', 6),
(413, 6, 'Chào đón nhân viên mới trong ngày đầu', 'Nhân viên mới hỏi về nhóm làm việc và các bước bắt đầu.', 3),
(414, 6, 'Xin nghỉ phép và bàn giao công việc', 'Nhân viên hỏi quy trình nghỉ phép và thống nhất bàn giao.', 4),
(415, 6, 'Trao đổi đánh giá hiệu suất với quản lý', 'Nhân viên trao đổi thành tích và mục tiêu phát triển.', 5),
(416, 6, 'Hỏi chương trình đào tạo nội bộ', 'Nhân viên hỏi nhân sự về khóa đào tạo và cách đăng ký.', 6),
(417, 7, 'Hỏi chuyển tiền quốc tế và phí giao dịch', 'Khách ngân hàng hỏi hồ sơ, phí và cách theo dõi chuyển tiền.', 3),
(418, 7, 'Báo sự cố rút tiền tại máy ATM', 'Khách liên hệ ngân hàng khi giao dịch rút tiền gặp vấn đề.', 4),
(419, 7, 'Hỏi thông tin hồ sơ vay vốn', 'Khách hỏi chuyên viên ngân hàng về hồ sơ và điều khoản vay.', 5),
(420, 7, 'Trao đổi mục tiêu tiết kiệm và ngân sách', 'Khách hỏi nhân viên ngân hàng về các lựa chọn tiết kiệm và điều kiện.', 6),
(421, 8, 'Kiểm tra chứng từ xuất nhập khẩu', 'Người gửi hàng trao đổi với nhân viên logistics về thông tin trên giấy tờ.', 3),
(422, 8, 'Báo kiện hàng bị hư hỏng', 'Người nhận mô tả tình trạng kiện hàng và hỏi quy trình báo cáo.', 4),
(423, 8, 'Đối chiếu tồn kho và số lượng hàng', 'Hai nhân viên kho kiểm tra số lượng thực tế với hệ thống.', 5),
(424, 8, 'Xin báo giá vận chuyển quốc tế', 'Doanh nghiệp hỏi phí, thời gian dự kiến và điều kiện vận chuyển.', 6),
(425, 9, 'Phản ánh tiếng ồn và xin hỗ trợ tại khách sạn', 'Khách phản ánh tiếng ồn với lễ tân và hỏi cách hỗ trợ.', 3),
(426, 9, 'Hỏi đồ thất lạc sau khi trả phòng', 'Khách liên hệ khách sạn để tìm món đồ bỏ quên.', 4),
(427, 9, 'Đặt bàn và xác nhận yêu cầu tại nhà hàng', 'Khách đặt bàn qua nhân viên nhà hàng và hỏi cách báo yêu cầu đặc biệt.', 5),
(428, 9, 'Đón khách và hướng dẫn tại hội nghị', 'Nhân viên sự kiện kiểm tra đăng ký và chỉ nơi tham dự.', 6),
(429, 10, 'Duyệt nội dung trước khi đăng chiến dịch', 'Khách hàng và người làm nội dung thống nhất bản nháp và các sửa đổi.', 3),
(430, 10, 'Thảo luận phản hồi khách trên mạng xã hội', 'Đồng nghiệp thống nhất cách phản hồi bình luận và chuyển vấn đề cho bộ phận phù hợp.', 4),
(431, 10, 'Trao đổi hợp tác thương hiệu và nhà sáng tạo', 'Đại diện thương hiệu và nhà sáng tạo trao đổi phạm vi công việc và quyền sử dụng.', 5),
(432, 10, 'Phỏng vấn khảo sát và xin góp ý khách hàng', 'Nhân viên khảo sát xin phép khách và hỏi trải nghiệm sử dụng dịch vụ.', 6);
INSERT INTO phrases (phrase_id,lesson_id,english_text,vietnamese_meaning,ipa_phonetic,audio_sample_url,context_note) VALUES
(40101, 401, 'What happened when you opened the page?', 'Chuyện gì xảy ra khi bạn mở trang?', '/wət ˈhæpənd wɪn ju ˈoʊpənd ðə peɪʤ/', '', 'PRACTICE_SENTENCE'),
(40102, 401, 'The page froze after I clicked the button.', 'Trang bị đứng sau khi tôi nhấn nút.', '/ðə peɪʤ froʊz ˈæftər aɪ klɪkt ðə ˈbətən/', '', 'PRACTICE_SENTENCE'),
(40103, 401, 'Can you show me the steps you followed?', 'Bạn chỉ tôi các bước đã làm nhé?', '/kən ju ʃoʊ mi ðə stɛps ju ˈfɑloʊd/', '', 'PRACTICE_SENTENCE'),
(40104, 401, 'browser', 'trình duyệt', '/ˈbraʊzər/', '', 'VOCABULARY'),
(40105, 401, 'freeze', 'bị đứng, đóng băng', '/friz/', '', 'VOCABULARY'),
(40106, 401, 'version', 'phiên bản', '/ˈvərʒən/', '', 'VOCABULARY'),
(40107, 401, 'First I signed in, then I opened the report.', 'Đầu tiên tôi đăng nhập, sau đó mở báo cáo.', '/fərst aɪ saɪnd ɪn, ðɛn aɪ ˈoʊpənd ðə rɪˈpɔrt/', '', 'PRACTICE_SENTENCE'),
(40108, 401, 'Does the problem happen every time?', 'Lỗi có xảy ra mỗi lần không?', '/dɪz ðə ˈprɑbləm ˈhæpən ˈɛvəri taɪm/', '', 'PRACTICE_SENTENCE'),
(40109, 401, 'It happens only when I use this browser.', 'Chỉ xảy ra khi tôi dùng trình duyệt này.', '/ɪt ˈhæpənz ˈoʊnli wɪn aɪ juz ðɪs ˈbraʊzər/', '', 'PRACTICE_SENTENCE'),
(40110, 401, 'I will record the details for our team.', 'Tôi sẽ ghi lại thông tin cho nhóm.', '/aɪ wɪl ˈrɛkərd ðə ˈditeɪlz fər ɑr tim/', '', 'PRACTICE_SENTENCE'),
(40111, 401, 'Thank you. Please let me know when it is fixed.', 'Cảm ơn. Vui lòng báo khi lỗi được sửa.', '/θæŋk ju. pliz lɛt mi noʊ wɪn ɪt ɪz fɪkst/', '', 'PRACTICE_SENTENCE'),
(40112, 401, 'Could you attach a screenshot to the report?', 'Bạn đính kèm ảnh chụp vào báo cáo nhé?', '/kʊd ju əˈtæʧ ə ˈskrinˌʃɑt tə ðə rɪˈpɔrt/', '', 'PRACTICE_SENTENCE'),
(40113, 401, 'Which version of the software are you using?', 'Bạn đang dùng phiên bản phần mềm nào?', '/wɪʧ ˈvərʒən əv ðə ˈsɔfˌwɛr ər ju ˈjuzɪŋ/', '', 'PRACTICE_SENTENCE'),
(40201, 402, 'What did you complete yesterday?', 'Hôm qua bạn hoàn thành việc gì?', '/wət dɪd ju kəmˈplit ˈjɛstərˌdeɪ/', '', 'PRACTICE_SENTENCE'),
(40202, 402, 'I finished testing the new feature.', 'Tôi đã kiểm thử xong tính năng mới.', '/aɪ ˈfɪnɪʃt ˈtɛstɪŋ ðə nu ˈfiʧər/', '', 'PRACTICE_SENTENCE'),
(40203, 402, 'Are there any problems slowing you down?', 'Có vấn đề nào làm bạn chậm lại không?', '/ər ðɛr ˈɛni ˈprɑbləmz sloʊɪŋ ju daʊn/', '', 'PRACTICE_SENTENCE'),
(40204, 402, 'priority', 'ưu tiên', '/praɪˈɔrəti/', '', 'VOCABULARY'),
(40205, 402, 'task', 'nhiệm vụ', '/tæsk/', '', 'VOCABULARY'),
(40206, 402, 'timeline', 'lịch trình', '/ˈtaɪmlaɪn/', '', 'VOCABULARY'),
(40207, 402, 'I am waiting for feedback from the design team.', 'Tôi đang chờ phản hồi từ đội thiết kế.', '/aɪ æm ˈweɪtɪŋ fər ˈfidˌbæk frəm ðə dɪˈzaɪn tim/', '', 'PRACTICE_SENTENCE'),
(40208, 402, 'What will you work on next?', 'Tiếp theo bạn sẽ làm gì?', '/wət wɪl ju wərk ɔn nɛkst/', '', 'PRACTICE_SENTENCE'),
(40209, 402, 'I will update the report and check the remaining tasks.', 'Tôi sẽ cập nhật báo cáo và kiểm tra việc còn lại.', '/aɪ wɪl ˈəpˌdeɪt ðə rɪˈpɔrt ənd ʧɛk ðə rɪˈmeɪnɪŋ tæsks/', '', 'PRACTICE_SENTENCE'),
(40210, 402, 'Please let me know if you need support.', 'Vui lòng báo nếu bạn cần hỗ trợ.', '/pliz lɛt mi noʊ ɪf ju nid səˈpɔrt/', '', 'PRACTICE_SENTENCE'),
(40211, 402, 'Thank you. I will keep the team informed.', 'Cảm ơn. Tôi sẽ cập nhật cho nhóm.', '/θæŋk ju. aɪ wɪl kip ðə tim ˌɪnˈfɔrmd/', '', 'PRACTICE_SENTENCE'),
(40212, 402, 'Could we clarify the priority for this task?', 'Chúng ta làm rõ mức ưu tiên của việc này nhé?', '/kʊd wi ˈklɛrəˌfaɪ ðə praɪˈɔrəti fər ðɪs tæsk/', '', 'PRACTICE_SENTENCE'),
(40213, 402, 'Do we need to adjust the timeline?', 'Chúng ta có cần điều chỉnh lịch trình không?', '/du wi nid tə əˈʤəst ðə ˈtaɪmlaɪn/', '', 'PRACTICE_SENTENCE'),
(40301, 403, 'Who needs access to this document?', 'Ai cần truy cập tài liệu này?', '/hu nidz ˈækˌsɛs tə ðɪs ˈdɑkjəmɛnt/', '', 'PRACTICE_SENTENCE'),
(40302, 403, 'Only the project team should be able to open it.', 'Chỉ nhóm dự án nên có quyền mở tài liệu.', '/ˈoʊnli ðə ˈprɑʤɛkt tim ʃʊd bi ˈeɪbəl tə ˈoʊpən ɪt/', '', 'PRACTICE_SENTENCE'),
(40303, 403, 'Does it contain personal information?', 'Nó có chứa thông tin cá nhân không?', '/dɪz ɪt kənˈteɪn ˈpərsɪnəl ˌɪnˌfɔrˈmeɪʃən/', '', 'PRACTICE_SENTENCE'),
(40304, 403, 'permission', 'quyền truy cập', '/pərˈmɪʃən/', '', 'VOCABULARY'),
(40305, 403, 'privacy', 'quyền riêng tư', '/ˈpraɪvəsi/', '', 'VOCABULARY'),
(40306, 403, 'secure', 'an toàn, bảo mật', '/sɪˈkjʊr/', '', 'VOCABULARY'),
(40307, 403, 'Yes. We need to handle it carefully.', 'Có. Chúng tôi cần xử lý cẩn thận.', '/jɛs. wi nid tə ˈhændəl ɪt ˈkɛrfəli/', '', 'PRACTICE_SENTENCE'),
(40308, 403, 'Have you checked the sharing permissions?', 'Bạn đã kiểm tra quyền chia sẻ chưa?', '/hæv ju ʧɛkt ðə ˈʃɛrɪŋ pərˈmɪʃənz/', '', 'PRACTICE_SENTENCE'),
(40309, 403, 'Could you help me check the settings?', 'Bạn giúp tôi kiểm tra cài đặt nhé?', '/kʊd ju hɛlp mi ʧɛk ðə ˈsɛtɪŋz/', '', 'PRACTICE_SENTENCE'),
(40310, 403, 'Of course. We will review the approved process.', 'Được. Chúng ta sẽ xem lại quy trình được phép.', '/əv kɔrs. wi wɪl ˌrivˈju ðə əˈpruvd ˈprɔˌsɛs/', '', 'PRACTICE_SENTENCE'),
(40311, 403, 'Thank you. I will follow the company policy.', 'Cảm ơn. Tôi sẽ làm theo chính sách công ty.', '/θæŋk ju. aɪ wɪl ˈfɑloʊ ðə ˈkəmpəˌni ˈpɑləsi/', '', 'PRACTICE_SENTENCE'),
(40312, 403, 'Please remove access when it is no longer needed.', 'Vui lòng thu hồi quyền truy cập khi không còn cần.', '/pliz riˈmuv ˈækˌsɛs wɪn ɪt ɪz noʊ ˈlɔŋgər ˈnidɪd/', '', 'PRACTICE_SENTENCE'),
(40313, 403, 'Which secure channel should I use to send the file?', 'Tôi nên dùng kênh an toàn nào để gửi tệp?', '/wɪʧ sɪˈkjʊr ˈʧænəl ʃʊd aɪ juz tə sɛnd ðə faɪl/', '', 'PRACTICE_SENTENCE'),
(40401, 404, 'Would you like me to show you the main features?', 'Bạn muốn tôi giới thiệu các tính năng chính không?', '/wʊd ju laɪk mi tə ʃoʊ ju ðə meɪn ˈfiʧərz/', '', 'PRACTICE_SENTENCE'),
(40402, 404, 'Yes. Could we start with the dashboard?', 'Có. Chúng ta bắt đầu với bảng điều khiển nhé?', '/jɛs. kʊd wi stɑrt wɪθ ðə ˈdæʃˌbɔrd/', '', 'PRACTICE_SENTENCE'),
(40403, 404, 'This menu lets you create a new record.', 'Menu này cho phép bạn tạo bản ghi mới.', '/ðɪs ˈmɛnju lɛts ju kriˈeɪt ə nu ˈrɛkərd/', '', 'PRACTICE_SENTENCE'),
(40404, 404, 'dashboard', 'bảng điều khiển', '/ˈdæʃˌbɔrd/', '', 'VOCABULARY'),
(40405, 404, 'record', 'bản ghi', '/ˈrɛkərd/', '', 'VOCABULARY'),
(40406, 404, 'save', 'lưu', '/seɪv/', '', 'VOCABULARY'),
(40407, 404, 'Where can I save my changes?', 'Tôi lưu thay đổi ở đâu?', '/wɛr kən aɪ seɪv maɪ ˈʧeɪnʤɪz/', '', 'PRACTICE_SENTENCE'),
(40408, 404, 'Use the save button at the bottom.', 'Dùng nút lưu ở phía dưới.', '/juz ðə seɪv ˈbətən æt ðə ˈbɑtəm/', '', 'PRACTICE_SENTENCE'),
(40409, 404, 'Could you demonstrate it one more time?', 'Bạn làm mẫu thêm một lần nhé?', '/kʊd ju ˈdɛmənˌstreɪt ɪt wən mɔr taɪm/', '', 'PRACTICE_SENTENCE'),
(40410, 404, 'Of course. Then you can try it yourself.', 'Được. Sau đó bạn có thể tự thử.', '/əv kɔrs. ðɛn ju kən traɪ ɪt ˈjɔrsɛlf/', '', 'PRACTICE_SENTENCE'),
(40411, 404, 'Thank you. I will ask if I get stuck.', 'Cảm ơn. Tôi sẽ hỏi nếu gặp khó khăn.', '/θæŋk ju. aɪ wɪl æsk ɪf aɪ gɪt stək/', '', 'PRACTICE_SENTENCE'),
(40412, 404, 'Is there a user guide I can read later?', 'Có hướng dẫn sử dụng để tôi đọc sau không?', '/ɪz ðɛr ə ˈjuzər gaɪd aɪ kən rɛd ˈleɪtər/', '', 'PRACTICE_SENTENCE'),
(40413, 404, 'How do I correct a mistake in the record?', 'Tôi sửa lỗi trong bản ghi bằng cách nào?', '/haʊ du aɪ kərˈɛkt ə mɪˈsteɪk ɪn ðə ˈrɛkərd/', '', 'PRACTICE_SENTENCE'),
(40501, 405, 'What would you like to discuss today?', 'Hôm nay bạn muốn trao đổi điều gì?', '/wət wʊd ju laɪk tə dɪˈskəs təˈdeɪ/', '', 'PRACTICE_SENTENCE'),
(40502, 405, 'I have been feeling tired recently.', 'Gần đây tôi cảm thấy mệt.', '/aɪ hæv bɪn ˈfilɪŋ taɪərd ˈrisəntli/', '', 'PRACTICE_SENTENCE'),
(40503, 405, 'When did you first notice it?', 'Bạn nhận thấy tình trạng này từ khi nào?', '/wɪn dɪd ju fərst ˈnoʊtɪs ɪt/', '', 'PRACTICE_SENTENCE'),
(40504, 405, 'symptom', 'triệu chứng', '/ˈsɪmptəm/', '', 'VOCABULARY'),
(40505, 405, 'history', 'tiền sử', '/ˈhɪstəri/', '', 'VOCABULARY'),
(40506, 405, 'tired', 'mệt mỏi', '/taɪərd/', '', 'VOCABULARY'),
(40507, 405, 'It started a few days ago.', 'Tình trạng bắt đầu vài ngày trước.', '/ɪt ˈstɑrtɪd ə fju deɪz əˈgoʊ/', '', 'PRACTICE_SENTENCE'),
(40508, 405, 'Is there anything else you want to mention?', 'Bạn còn muốn nói thêm điều gì không?', '/ɪz ðɛr ˈɛniˌθɪŋ ɛls ju wɔnt tə ˈmɛnʃən/', '', 'PRACTICE_SENTENCE'),
(40509, 405, 'I also want to discuss my sleep.', 'Tôi cũng muốn trao đổi về giấc ngủ.', '/aɪ ˈɔlsoʊ wɔnt tə dɪˈskəs maɪ slip/', '', 'PRACTICE_SENTENCE'),
(40510, 405, 'Thank you for explaining. We will review your history.', 'Cảm ơn đã giải thích. Chúng ta sẽ xem tiền sử của bạn.', '/θæŋk ju fər ɪkˈspleɪnɪŋ. wi wɪl ˌrivˈju jʊr ˈhɪstəri/', '', 'PRACTICE_SENTENCE'),
(40511, 405, 'Could you explain the next steps to me?', 'Bác sĩ giải thích các bước tiếp theo giúp tôi nhé?', '/kʊd ju ɪkˈspleɪn ðə nɛkst stɛps tə mi/', '', 'PRACTICE_SENTENCE'),
(40512, 405, 'Please let me know if you need more details.', 'Vui lòng cho biết nếu cần thêm thông tin.', '/pliz lɛt mi noʊ ɪf ju nid mɔr ˈditeɪlz/', '', 'PRACTICE_SENTENCE'),
(40513, 405, 'Could I have a written summary of the visit?', 'Tôi xin bản tóm tắt buổi khám bằng văn bản nhé?', '/kʊd aɪ hæv ə ˈrɪtən ˈsəməri əv ðə ˈvɪzɪt/', '', 'PRACTICE_SENTENCE'),
(40601, 406, 'Do you have a referral for the test?', 'Bạn có giấy chỉ định xét nghiệm không?', '/du ju hæv ə rɪˈfərəl fər ðə tɛst/', '', 'PRACTICE_SENTENCE'),
(40602, 406, 'Yes. I would like to book a time.', 'Có. Tôi muốn đặt lịch.', '/jɛs. aɪ wʊd laɪk tə bʊk ə taɪm/', '', 'PRACTICE_SENTENCE'),
(40603, 406, 'Which day would suit you?', 'Ngày nào phù hợp với bạn?', '/wɪʧ deɪ wʊd sut ju/', '', 'PRACTICE_SENTENCE'),
(40604, 406, 'referral', 'giấy chuyển hoặc chỉ định', '/rɪˈfərəl/', '', 'VOCABULARY'),
(40605, 406, 'preparation', 'sự chuẩn bị', '/ˌprɛpərˈeɪʃən/', '', 'VOCABULARY'),
(40606, 406, 'result', 'kết quả', '/rɪˈzəlt/', '', 'VOCABULARY'),
(40607, 406, 'Could you tell me the available times?', 'Bạn cho tôi biết các giờ còn trống nhé?', '/kʊd ju tɛl mi ðə əˈveɪləbəl taɪmz/', '', 'PRACTICE_SENTENCE'),
(40608, 406, 'Have you received the preparation instructions?', 'Bạn đã nhận hướng dẫn chuẩn bị chưa?', '/hæv ju rɪˈsivd ðə ˌprɛpərˈeɪʃən ˌɪnˈstrəkʃənz/', '', 'PRACTICE_SENTENCE'),
(40609, 406, 'Not yet. Could you send them to me?', 'Chưa. Bạn gửi cho tôi nhé?', '/nɑt jɛt. kʊd ju sɛnd ðɛm tə mi/', '', 'PRACTICE_SENTENCE'),
(40610, 406, 'Of course. Please follow the instructions from your clinician.', 'Được. Hãy làm theo hướng dẫn của nhân viên y tế.', '/əv kɔrs. pliz ˈfɑloʊ ðə ˌɪnˈstrəkʃənz frəm jʊr klɪˈnɪʃən/', '', 'PRACTICE_SENTENCE'),
(40611, 406, 'Thank you. Who can I call if I have questions?', 'Cảm ơn. Tôi gọi ai nếu có thắc mắc?', '/θæŋk ju. hu kən aɪ kɔl ɪf aɪ hæv kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(40612, 406, 'Where should I go when I arrive?', 'Khi đến tôi nên đi tới đâu?', '/wɛr ʃʊd aɪ goʊ wɪn aɪ əraɪv/', '', 'PRACTICE_SENTENCE'),
(40613, 406, 'How will I receive the test results?', 'Tôi sẽ nhận kết quả xét nghiệm bằng cách nào?', '/haʊ wɪl aɪ rɪˈsiv ðə tɛst rɪˈzəlts/', '', 'PRACTICE_SENTENCE'),
(40701, 407, 'Which records would you like to request?', 'Bạn muốn xin hồ sơ nào?', '/wɪʧ ˈrɛkərdz wʊd ju laɪk tə rɪkˈwɛst/', '', 'PRACTICE_SENTENCE'),
(40702, 407, 'I would like a copy of my recent visit summary.', 'Tôi muốn bản sao tóm tắt lần khám gần đây.', '/aɪ wʊd laɪk ə ˈkɑpi əv maɪ ˈrisənt ˈvɪzɪt ˈsəməri/', '', 'PRACTICE_SENTENCE'),
(40703, 407, 'We need to verify your identity first.', 'Trước tiên chúng tôi cần xác minh danh tính.', '/wi nid tə ˈvɛrəˌfaɪ jʊr aɪˈdɛntəˌti fərst/', '', 'PRACTICE_SENTENCE'),
(40704, 407, 'identity', 'danh tính', '/aɪˈdɛntəˌti/', '', 'VOCABULARY'),
(40705, 407, 'request', 'yêu cầu', '/rɪkˈwɛst/', '', 'VOCABULARY'),
(40706, 407, 'copy', 'bản sao', '/ˈkɑpi/', '', 'VOCABULARY'),
(40707, 407, 'What documents should I provide?', 'Tôi cần cung cấp giấy tờ nào?', '/wət ˈdɑkjəmənts ʃʊd aɪ prəˈvaɪd/', '', 'PRACTICE_SENTENCE'),
(40708, 407, 'Please complete the request form.', 'Vui lòng điền phiếu yêu cầu.', '/pliz kəmˈplit ðə rɪkˈwɛst fɔrm/', '', 'PRACTICE_SENTENCE'),
