(40804, 408, 'department', 'khoa, bộ phận', '/dɪˈpɑrtmənt/', '', 'VOCABULARY'),
(40805, 408, 'outpatient', 'người khám ngoại trú', '/ˈaʊtˌpeɪʃənt/', '', 'VOCABULARY'),
(40806, 408, 'waiting area', 'khu vực chờ', '/ˈweɪtɪŋ ˈɛriə/', '', 'VOCABULARY'),
(40807, 408, 'Yes. Could you check which floor I need?', 'Có. Bạn kiểm tra giúp tôi cần đến tầng nào nhé?', '/jɛs. kʊd ju ʧɛk wɪʧ flɔr aɪ nid/', '', 'PRACTICE_SENTENCE'),
(40808, 408, 'I can show you the route on this map.', 'Tôi có thể chỉ đường trên bản đồ này.', '/aɪ kən ʃoʊ ju ðə rut ɔn ðɪs mæp/', '', 'PRACTICE_SENTENCE'),
(40809, 408, 'Is there a lift nearby?', 'Có thang máy gần đây không?', '/ɪz ðɛr ə lɪft ˈnɪrˈbaɪ/', '', 'PRACTICE_SENTENCE'),
(40810, 408, 'Yes. Please follow the signs to the waiting area.', 'Có. Hãy đi theo biển chỉ dẫn tới khu chờ.', '/jɛs. pliz ˈfɑloʊ ðə saɪnz tə ðə ˈweɪtɪŋ ˈɛriə/', '', 'PRACTICE_SENTENCE'),
(40811, 408, 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.', '/θæŋk ju fər jʊr hɛlp/', '', 'PRACTICE_SENTENCE'),
(40812, 408, 'Where can I ask for assistance with a wheelchair?', 'Tôi hỏi hỗ trợ xe lăn ở đâu?', '/wɛr kən aɪ æsk fər əˈsɪstəns wɪθ ə ˈwiˌlʧɛr/', '', 'PRACTICE_SENTENCE'),
(40813, 408, 'Could you point out the reception desk?', 'Bạn chỉ quầy tiếp nhận giúp tôi nhé?', '/kʊd ju pɔɪnt aʊt ðə rɪˈsɛpʃən dɛsk/', '', 'PRACTICE_SENTENCE'),
(40901, 409, 'Which book are you looking for?', 'Bạn đang tìm sách nào?', '/wɪʧ bʊk ər ju ˈlʊkɪŋ fər/', '', 'PRACTICE_SENTENCE'),
(40902, 409, 'I need a book about business communication.', 'Tôi cần sách về giao tiếp kinh doanh.', '/aɪ nid ə bʊk əˈbaʊt ˈbɪznɪs kəmˌjunəˈkeɪʃən/', '', 'PRACTICE_SENTENCE'),
