(40910, 409, 'Please check the due date on your account.', 'Hãy xem hạn trả trong tài khoản.', '/pliz ʧɛk ðə du deɪt ɔn jʊr əˈkaʊnt/', '', 'PRACTICE_SENTENCE'),
(40911, 409, 'Thank you. Can I renew it online?', 'Cảm ơn. Tôi gia hạn trực tuyến được không?', '/θæŋk ju. kən aɪ rɪˈnu ɪt ˈɔnˌlaɪn/', '', 'PRACTICE_SENTENCE'),
(40912, 409, 'Where should I return the books?', 'Tôi trả sách ở đâu?', '/wɛr ʃʊd aɪ rɪˈtərn ðə bʊks/', '', 'PRACTICE_SENTENCE'),
(40913, 409, 'Is there a quiet study area?', 'Có khu vực học yên tĩnh không?', '/ɪz ðɛr ə kwaɪət ˈstədi ˈɛriə/', '', 'PRACTICE_SENTENCE'),
(41001, 410, 'Which part of the project would you like to work on?', 'Bạn muốn làm phần nào của dự án?', '/wɪʧ pɑrt əv ðə ˈprɑʤɛkt wʊd ju laɪk tə wərk ɔn/', '', 'PRACTICE_SENTENCE'),
(41002, 410, 'I can research the background information.', 'Tôi có thể nghiên cứu thông tin nền.', '/aɪ kən ˈrisərʧ ðə ˈbækˌgraʊnd ˌɪnˌfɔrˈmeɪʃən/', '', 'PRACTICE_SENTENCE'),
(41003, 410, 'Who will prepare the presentation?', 'Ai sẽ chuẩn bị bài thuyết trình?', '/hu wɪl priˈpɛr ðə ˌprɛzənˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
(41004, 410, 'research', 'nghiên cứu', '/ˈrisərʧ/', '', 'VOCABULARY'),
(41005, 410, 'slide', 'trang trình chiếu', '/slaɪd/', '', 'VOCABULARY'),
(41006, 410, 'progress', 'tiến độ', '/ˈprɑˌgrɛs/', '', 'VOCABULARY'),
(41007, 410, 'Could we work on the slides together?', 'Chúng ta cùng làm các trang trình chiếu nhé?', '/kʊd wi wərk ɔn ðə slaɪdz təˈgɛðər/', '', 'PRACTICE_SENTENCE'),
(41008, 410, 'When should we review our progress?', 'Khi nào nên kiểm tra tiến độ?', '/wɪn ʃʊd wi ˌrivˈju ɑr ˈprɑˌgrɛs/', '', 'PRACTICE_SENTENCE'),
(41009, 410, 'Let us meet after class on Thursday.', 'Chúng ta gặp sau giờ học thứ Năm nhé.', '/lɛt ˈjuˈɛs mit ˈæftər klæs ɔn ˈθərzˌdeɪ/', '', 'PRACTICE_SENTENCE'),
