(41011, 410, 'Great. We can combine our ideas at the meeting.', 'Tốt. Chúng ta có thể tổng hợp ý tưởng khi họp.', '/greɪt. wi kən ˈkɑmbaɪn ɑr aɪˈdiəz æt ðə ˈmitɪŋ/', '', 'PRACTICE_SENTENCE'),
(41012, 410, 'Please let the group know if you need help.', 'Hãy báo nhóm nếu bạn cần giúp đỡ.', '/pliz lɛt ðə grup noʊ ɪf ju nid hɛlp/', '', 'PRACTICE_SENTENCE'),
(41013, 410, 'How should we divide the remaining tasks?', 'Chúng ta chia các việc còn lại thế nào?', '/haʊ ʃʊd wi dɪˈvaɪd ðə rɪˈmeɪnɪŋ tæsks/', '', 'PRACTICE_SENTENCE'),
