(41102, 411, 'I would like information about the international scholarship.', 'Tôi muốn thông tin về học bổng quốc tế.', '/aɪ wʊd laɪk ˌɪnˌfɔrˈmeɪʃən əˈbaʊt ðə ˌɪnərˈnæʃənɑl ˈskɑlərˌʃɪp/', '', 'PRACTICE_SENTENCE'),
(41103, 411, 'Have you read the eligibility criteria?', 'Bạn đã đọc tiêu chí đủ điều kiện chưa?', '/hæv ju rɛd ðə ˌɛlɪʤəˈbɪlɪti kraɪˈtɪriə/', '', 'PRACTICE_SENTENCE'),
(41104, 411, 'scholarship', 'học bổng', '/ˈskɑlərˌʃɪp/', '', 'VOCABULARY'),
(41105, 411, 'eligibility', 'điều kiện đủ tiêu chuẩn', '/ˌɛlɪʤəˈbɪlɪti/', '', 'VOCABULARY'),
(41106, 411, 'application', 'hồ sơ đăng ký', '/ˌæpləˈkeɪʃən/', '', 'VOCABULARY'),
