(41110, 411, 'Please check the official application page.', 'Hãy kiểm tra trang đăng ký chính thức.', '/pliz ʧɛk ðə əˈfɪʃəl ˌæpləˈkeɪʃən peɪʤ/', '', 'PRACTICE_SENTENCE'),
(41111, 411, 'Thank you. Who can review my questions?', 'Cảm ơn. Ai có thể giải đáp thắc mắc của tôi?', '/θæŋk ju. hu kən ˌrivˈju maɪ kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(41112, 411, 'Can I ask for advice before submitting the form?', 'Tôi xin tư vấn trước khi nộp biểu mẫu được không?', '/kən aɪ æsk fər ədˈvaɪs ˌbiˈfɔr səbˈmɪtɪŋ ðə fɔrm/', '', 'PRACTICE_SENTENCE'),
(41113, 411, 'How will I be notified of the decision?', 'Tôi sẽ được thông báo kết quả bằng cách nào?', '/haʊ wɪl aɪ bi ˈnoʊtəˌfaɪd əv ðə dɪˈsɪʒən/', '', 'PRACTICE_SENTENCE'),
(41201, 412, 'How do you feel about your presentation?', 'Bạn thấy bài thuyết trình của mình thế nào?', '/haʊ du ju fil əˈbaʊt jʊr ˌprɛzənˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
(41202, 412, 'I think I need to improve the structure.', 'Em nghĩ cần cải thiện bố cục.', '/aɪ θɪŋk aɪ nid tə ˌɪmˈpruv ðə ˈstrəkʧər/', '', 'PRACTICE_SENTENCE'),
(41203, 412, 'Your main points were clear.', 'Các ý chính của em khá rõ.', '/jʊr meɪn pɔɪnts wər klɪr/', '', 'PRACTICE_SENTENCE'),
(41204, 412, 'structure', 'bố cục', '/ˈstrəkʧər/', '', 'VOCABULARY'),
(41205, 412, 'introduction', 'phần mở đầu', '/ˌɪntrəˈdəkʃən/', '', 'VOCABULARY'),
(41206, 412, 'conclusion', 'kết luận', '/kənˈkluʒən/', '', 'VOCABULARY'),
(41207, 412, 'Could you suggest how to improve the introduction?', 'Thầy cô gợi ý cách cải thiện phần mở đầu nhé?', '/kʊd ju səˈʤɛst haʊ tə ˌɪmˈpruv ðə ˌɪntrəˈdəkʃən/', '', 'PRACTICE_SENTENCE'),
(41208, 412, 'Try to explain the purpose at the beginning.', 'Hãy giải thích mục đích ngay từ đầu.', '/traɪ tə ɪkˈspleɪn ðə ˈpərpəs æt ðə bɪˈgɪnɪŋ/', '', 'PRACTICE_SENTENCE'),
(41209, 412, 'Should I use fewer slides?', 'Em có nên dùng ít trang trình chiếu hơn không?', '/ʃʊd aɪ juz fjuər slaɪdz/', '', 'PRACTICE_SENTENCE'),
(41210, 412, 'Focus on the key ideas and practise your timing.', 'Hãy tập trung ý chính và luyện thời gian trình bày.', '/ˈfoʊkɪs ɔn ðə ki aɪˈdiəz ənd ˈpræktɪs jʊr ˈtaɪmɪŋ/', '', 'PRACTICE_SENTENCE'),
(41211, 412, 'Thank you. I will revise my presentation.', 'Cảm ơn. Em sẽ chỉnh sửa bài thuyết trình.', '/θæŋk ju. aɪ wɪl rɪˈvaɪz maɪ ˌprɛzənˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
