(41213, 412, 'May I ask for feedback on the revised version?', 'Em xin góp ý cho bản chỉnh sửa được không?', '/meɪ aɪ æsk fər ˈfidˌbæk ɔn ðə rɪˈvaɪzd ˈvərʒən/', '', 'PRACTICE_SENTENCE'),
(41301, 413, 'Welcome to the team. How are you feeling?', 'Chào mừng đến với nhóm. Bạn cảm thấy thế nào?', '/ˈwɛlkəm tə ðə tim. haʊ ər ju ˈfilɪŋ/', '', 'PRACTICE_SENTENCE'),
(41302, 413, 'I am excited to get started.', 'Tôi rất háo hức bắt đầu.', '/aɪ æm ɪkˈsaɪtɪd tə gɪt ˈstɑrtɪd/', '', 'PRACTICE_SENTENCE'),
(41303, 413, 'We will introduce you to your colleagues.', 'Chúng tôi sẽ giới thiệu bạn với đồng nghiệp.', '/wi wɪl ˌɪntrəˈdus ju tə jʊr ˈkɑligz/', '', 'PRACTICE_SENTENCE'),
(41304, 413, 'colleague', 'đồng nghiệp', '/ˈkɑlig/', '', 'VOCABULARY'),
(41305, 413, 'handbook', 'sổ tay', '/ˈhændˌbʊk/', '', 'VOCABULARY'),
(41306, 413, 'workspace', 'không gian làm việc', '/ˈwɜrkˌspeɪs/', '', 'VOCABULARY'),
(41307, 413, 'Who should I contact if I have questions?', 'Tôi liên hệ ai nếu có câu hỏi?', '/hu ʃʊd aɪ ˈkɑnˌtækt ɪf aɪ hæv kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(41308, 413, 'Your manager will explain the first tasks.', 'Quản lý sẽ giải thích các nhiệm vụ đầu tiên.', '/jʊr ˈmænɪʤər wɪl ɪkˈspleɪn ðə fərst tæsks/', '', 'PRACTICE_SENTENCE'),
(41309, 413, 'Is there a schedule for the first week?', 'Có lịch cho tuần đầu không?', '/ɪz ðɛr ə ˈskɛʤʊl fər ðə fərst wik/', '', 'PRACTICE_SENTENCE'),
(41310, 413, 'Yes. I will send it to your email.', 'Có. Tôi sẽ gửi qua email.', '/jɛs. aɪ wɪl sɛnd ɪt tə jʊr iˈmeɪl/', '', 'PRACTICE_SENTENCE'),
(41311, 413, 'Thank you. I look forward to meeting everyone.', 'Cảm ơn. Tôi mong được gặp mọi người.', '/θæŋk ju. aɪ lʊk ˈfɔrwərd tə ˈmitɪŋ ˈɛvriˌwən/', '', 'PRACTICE_SENTENCE'),
(41312, 413, 'Where can I find the staff handbook?', 'Tôi tìm sổ tay nhân viên ở đâu?', '/wɛr kən aɪ faɪnd ðə stæf ˈhændˌbʊk/', '', 'PRACTICE_SENTENCE'),
(41313, 413, 'Could you show me the shared workspace?', 'Bạn chỉ tôi khu làm việc chung nhé?', '/kʊd ju ʃoʊ mi ðə ʃɛrd ˈwɜrkˌspeɪs/', '', 'PRACTICE_SENTENCE'),
(41401, 414, 'Which dates would you like to request?', 'Bạn muốn xin nghỉ những ngày nào?', '/wɪʧ deɪts wʊd ju laɪk tə rɪkˈwɛst/', '', 'PRACTICE_SENTENCE'),
(41402, 414, 'I would like to take leave next week.', 'Tôi muốn nghỉ phép tuần tới.', '/aɪ wʊd laɪk tə teɪk liv nɛkst wik/', '', 'PRACTICE_SENTENCE'),
(41403, 414, 'Have you checked the team schedule?', 'Bạn đã xem lịch của nhóm chưa?', '/hæv ju ʧɛkt ðə tim ˈskɛʤʊl/', '', 'PRACTICE_SENTENCE'),
(41404, 414, 'leave', 'nghỉ phép', '/liv/', '', 'VOCABULARY'),
(41405, 414, 'handover', 'bàn giao', '/ˈhændoʊvər/', '', 'VOCABULARY'),
(41406, 414, 'urgent', 'khẩn cấp', '/ˈərʤənt/', '', 'VOCABULARY'),
(41407, 414, 'Yes. I can finish the urgent tasks before then.', 'Có. Tôi có thể xong các việc gấp trước đó.', '/jɛs. aɪ kən ˈfɪnɪʃ ðə ˈərʤənt tæsks ˌbiˈfɔr ðɛn/', '', 'PRACTICE_SENTENCE'),
