(41506, 415, 'goal', 'mục tiêu', '/goʊl/', '', 'VOCABULARY'),
(41507, 415, 'I needed more practice with the new system.', 'Tôi cần thực hành thêm với hệ thống mới.', '/aɪ ˈnidɪd mɔr ˈpræktɪs wɪθ ðə nu ˈsɪstəm/', '', 'PRACTICE_SENTENCE'),
