(41511, 415, 'Thank you. I would appreciate regular feedback.', 'Cảm ơn. Tôi mong nhận phản hồi thường xuyên.', '/θæŋk ju. aɪ wʊd əˈpriʃiˌeɪt ˈrɛgjələr ˈfidˌbæk/', '', 'PRACTICE_SENTENCE'),
(41512, 415, 'How will we measure progress towards these goals?', 'Chúng ta đo tiến độ đạt mục tiêu thế nào?', '/haʊ wɪl wi ˈmɛʒər ˈprɑˌgrɛs təˈwɔrdz ðiz goʊlz/', '', 'PRACTICE_SENTENCE'),
(41513, 415, 'When should we review the plan again?', 'Khi nào nên xem lại kế hoạch?', '/wɪn ʃʊd wi ˌrivˈju ðə plæn əˈgɛn/', '', 'PRACTICE_SENTENCE'),
(41601, 416, 'Which skills would you like to develop?', 'Bạn muốn phát triển kỹ năng nào?', '/wɪʧ skɪlz wʊd ju laɪk tə dɪˈvɛləp/', '', 'PRACTICE_SENTENCE'),
(41602, 416, 'I would like to improve my communication skills.', 'Tôi muốn cải thiện kỹ năng giao tiếp.', '/aɪ wʊd laɪk tə ˌɪmˈpruv maɪ kəmˌjunəˈkeɪʃən skɪlz/', '', 'PRACTICE_SENTENCE'),
