(41904, 419, 'loan', 'khoản vay', '/loʊn/', '', 'VOCABULARY'),
(41905, 419, 'repayment', 'trả nợ', '/riˈpeɪmənt/', '', 'VOCABULARY'),
(41906, 419, 'interest', 'lãi', '/ˈɪntəˌrɛst/', '', 'VOCABULARY'),
(41907, 419, 'Which documents should I prepare?', 'Tôi nên chuẩn bị giấy tờ nào?', '/wɪʧ ˈdɑkjəmənts ʃʊd aɪ priˈpɛr/', '', 'PRACTICE_SENTENCE'),
