(42003, 420, 'Do you need access to the money regularly?', 'Bạn có cần rút tiền thường xuyên không?', '/du ju nid ˈækˌsɛs tə ðə ˈməni ˈrɛgjələrli/', '', 'PRACTICE_SENTENCE'),
