(42006, 420, 'condition', 'điều kiện', '/kənˈdɪʃən/', '', 'VOCABULARY'),
(42007, 420, 'I would like to understand the withdrawal conditions.', 'Tôi muốn hiểu điều kiện rút tiền.', '/aɪ wʊd laɪk tə ˌəndərˈstænd ðə wɪθˈdrɔəl kənˈdɪʃənz/', '', 'PRACTICE_SENTENCE'),
