(42711, 427, 'Thank you. How will I receive the confirmation?', 'Cảm ơn. Tôi sẽ nhận xác nhận bằng cách nào?', '/θæŋk ju. haʊ wɪl aɪ rɪˈsiv ðə ˌkɑnfərˈmeɪʃən/', '', 'PRACTICE_SENTENCE'),
(42712, 427, 'Who should I contact if our plans change?', 'Tôi liên hệ ai nếu kế hoạch thay đổi?', '/hu ʃʊd aɪ ˈkɑnˌtækt ɪf ɑr plænz ʧeɪnʤ/', '', 'PRACTICE_SENTENCE'),
(42713, 427, 'Can I mention a food allergy when I book?', 'Tôi có thể báo dị ứng thực phẩm khi đặt bàn không?', '/kən aɪ ˈmɛnʃən ə fud ˈælərʤi wɪn aɪ bʊk/', '', 'PRACTICE_SENTENCE'),
(42801, 428, 'Welcome. Have you registered for the conference?', 'Xin chào. Bạn đã đăng ký hội nghị chưa?', '/ˈwɛlkəm. hæv ju ˈrɛʤɪstərd fər ðə ˈkɑnfərəns/', '', 'PRACTICE_SENTENCE'),
(42802, 428, 'Yes. Here is my confirmation email.', 'Có. Đây là email xác nhận của tôi.', '/jɛs. hir ɪz maɪ ˌkɑnfərˈmeɪʃən iˈmeɪl/', '', 'PRACTICE_SENTENCE'),
(42803, 428, 'Could I check the name on your registration?', 'Tôi kiểm tra tên trong đăng ký nhé?', '/kʊd aɪ ʧɛk ðə neɪm ɔn jʊr ˌrɛʤɪˈstreɪʃən/', '', 'PRACTICE_SENTENCE'),
(42804, 428, 'badge', 'thẻ tên', '/bæʤ/', '', 'VOCABULARY'),
(42805, 428, 'conference', 'hội nghị', '/ˈkɑnfərəns/', '', 'VOCABULARY'),
(42806, 428, 'session', 'phiên họp', '/ˈsɛʃən/', '', 'VOCABULARY'),
(42807, 428, 'Of course. My name is on this page.', 'Được. Tên tôi ở trang này.', '/əv kɔrs. maɪ neɪm ɪz ɔn ðɪs peɪʤ/', '', 'PRACTICE_SENTENCE'),
(42808, 428, 'Here is your badge and the event schedule.', 'Đây là thẻ tên và lịch sự kiện.', '/hir ɪz jʊr bæʤ ənd ðə ɪˈvɛnt ˈskɛʤʊl/', '', 'PRACTICE_SENTENCE'),
(42809, 428, 'Where is the opening session being held?', 'Phiên khai mạc diễn ra ở đâu?', '/wɛr ɪz ðə ˈoʊpənɪŋ ˈsɛʃən biɪŋ hɛld/', '', 'PRACTICE_SENTENCE'),
(42810, 428, 'Please follow the signs to the main hall.', 'Hãy theo biển chỉ dẫn tới hội trường chính.', '/pliz ˈfɑloʊ ðə saɪnz tə ðə meɪn hɔl/', '', 'PRACTICE_SENTENCE'),
(42811, 428, 'Thank you. Could you also show me the help desk?', 'Cảm ơn. Bạn chỉ cả quầy hỗ trợ giúp tôi nhé?', '/θæŋk ju. kʊd ju ˈɔlsoʊ ʃoʊ mi ðə hɛlp dɛsk/', '', 'PRACTICE_SENTENCE'),
(42812, 428, 'Are there any changes to the programme?', 'Chương trình có thay đổi nào không?', '/ər ðɛr ˈɛni ˈʧeɪnʤɪz tə ðə ˈproʊˌgræm/', '', 'PRACTICE_SENTENCE'),
(42813, 428, 'Where can I ask about access requirements?', 'Tôi hỏi về nhu cầu hỗ trợ tiếp cận ở đâu?', '/wɛr kən aɪ æsk əˈbaʊt ˈækˌsɛs rɪkˈwaɪrmənts/', '', 'PRACTICE_SENTENCE'),
(42901, 429, 'Have you had a chance to review the draft?', 'Bạn đã có dịp xem bản nháp chưa?', '/hæv ju hæd ə ʧæns tə ˌrivˈju ðə dræft/', '', 'PRACTICE_SENTENCE'),
(42902, 429, 'Yes. I would like to suggest a few changes.', 'Có. Tôi muốn đề nghị vài thay đổi.', '/jɛs. aɪ wʊd laɪk tə səˈʤɛst ə fju ˈʧeɪnʤɪz/', '', 'PRACTICE_SENTENCE'),
(42903, 429, 'Which part would you like us to revise?', 'Bạn muốn chúng tôi sửa phần nào?', '/wɪʧ pɑrt wʊd ju laɪk ˈjuˈɛs tə rɪˈvaɪz/', '', 'PRACTICE_SENTENCE'),
(42904, 429, 'draft', 'bản nháp', '/dræft/', '', 'VOCABULARY'),
(42905, 429, 'tone', 'giọng điệu', '/toʊn/', '', 'VOCABULARY'),
(42906, 429, 'publish', 'đăng, xuất bản', '/ˈpəblɪʃ/', '', 'VOCABULARY'),
(42907, 429, 'Could we make the opening message clearer?', 'Chúng ta làm thông điệp mở đầu rõ hơn nhé?', '/kʊd wi meɪk ðə ˈoʊpənɪŋ ˈmɛsɪʤ ˈklɪrər/', '', 'PRACTICE_SENTENCE'),
(42908, 429, 'Of course. Do you have any style preferences?', 'Được. Bạn có sở thích về phong cách không?', '/əv kɔrs. du ju hæv ˈɛni staɪl ˈprɛfərənsɪz/', '', 'PRACTICE_SENTENCE'),
(42909, 429, 'Please keep the tone friendly and professional.', 'Hãy giữ giọng điệu thân thiện và chuyên nghiệp.', '/pliz kip ðə toʊn ˈfrɛndli ənd prəˈfɛʃənəl/', '', 'PRACTICE_SENTENCE'),
(42910, 429, 'We will send an updated version for approval.', 'Chúng tôi sẽ gửi bản cập nhật để duyệt.', '/wi wɪl sɛnd ən ˈəpˌdeɪtɪd ˈvərʒən fər əˈpruvəl/', '', 'PRACTICE_SENTENCE'),
(42911, 429, 'Thank you. Please wait for approval before publishing.', 'Cảm ơn. Vui lòng chờ duyệt trước khi đăng.', '/θæŋk ju. pliz weɪt fər əˈpruvəl ˌbiˈfɔr ˈpəblɪʃɪŋ/', '', 'PRACTICE_SENTENCE'),
(42912, 429, 'Could you explain why you chose this image?', 'Bạn giải thích vì sao chọn ảnh này nhé?', '/kʊd ju ɪkˈspleɪn waɪ ju ʧoʊz ðɪs ˈɪmɪʤ/', '', 'PRACTICE_SENTENCE'),
(42913, 429, 'When can we expect the revised draft?', 'Khi nào chúng tôi nhận bản nháp chỉnh sửa?', '/wɪn kən wi ɪkˈspɛkt ðə rɪˈvaɪzd dræft/', '', 'PRACTICE_SENTENCE'),
(43001, 430, 'What feedback have we received today?', 'Hôm nay chúng ta nhận phản hồi gì?', '/wət ˈfidˌbæk hæv wi rɪˈsivd təˈdeɪ/', '', 'PRACTICE_SENTENCE'),
(43002, 430, 'Some customers are asking about the delivery time.', 'Một số khách hỏi về thời gian giao hàng.', '/səm ˈkəstəmərz ər ˈæskɪŋ əˈbaʊt ðə dɪˈlɪvəri taɪm/', '', 'PRACTICE_SENTENCE'),
(43003, 430, 'Have we confirmed the latest information?', 'Chúng ta xác nhận thông tin mới nhất chưa?', '/hæv wi kənˈfərmd ðə ˈleɪtəst ˌɪnˌfɔrˈmeɪʃən/', '', 'PRACTICE_SENTENCE'),
(43004, 430, 'comment', 'bình luận', '/ˈkɑmɛnt/', '', 'VOCABULARY'),
(43005, 430, 'respond', 'phản hồi', '/rɪˈspɑnd/', '', 'VOCABULARY'),
(43006, 430, 'publicly', 'công khai', '/ˈpəblɪkli/', '', 'VOCABULARY'),
(43007, 430, 'I will check with the customer service team.', 'Tôi sẽ kiểm tra với bộ phận chăm sóc khách.', '/aɪ wɪl ʧɛk wɪθ ðə ˈkəstəmər ˈsərvɪs tim/', '', 'PRACTICE_SENTENCE'),
(43008, 430, 'How should we respond to the comments?', 'Chúng ta nên trả lời bình luận thế nào?', '/haʊ ʃʊd wi rɪˈspɑnd tə ðə ˈkɑmɛnts/', '', 'PRACTICE_SENTENCE'),
(43009, 430, 'We should give clear information and be polite.', 'Chúng ta nên cung cấp thông tin rõ và lịch sự.', '/wi ʃʊd gɪv klɪr ˌɪnˌfɔrˈmeɪʃən ənd bi pəˈlaɪt/', '', 'PRACTICE_SENTENCE'),
(43010, 430, 'Please send sensitive issues through the approved channel.', 'Hãy chuyển vấn đề nhạy cảm qua kênh được phép.', '/pliz sɛnd ˈsɛnsɪtɪv ˈɪʃuz θru ðə əˈpruvd ˈʧænəl/', '', 'PRACTICE_SENTENCE'),
(43011, 430, 'Understood. I will not post personal details publicly.', 'Tôi hiểu. Tôi sẽ không đăng thông tin cá nhân công khai.', '/ˌəndərˈstʊd. aɪ wɪl nɑt poʊst ˈpərsɪnəl ˈditeɪlz ˈpəblɪkli/', '', 'PRACTICE_SENTENCE'),
(43012, 430, 'Could we prepare a standard response for common questions?', 'Chúng ta chuẩn bị câu trả lời chuẩn cho câu hỏi thường gặp nhé?', '/kʊd wi priˈpɛr ə ˈstændərd rɪˈspɑns fər ˈkɑmən kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(43013, 430, 'Who should review the reply before it is posted?', 'Ai nên xem lại câu trả lời trước khi đăng?', '/hu ʃʊd ˌrivˈju ðə rɪˈplaɪ ˌbiˈfɔr ɪt ɪz ˈpoʊstɪd/', '', 'PRACTICE_SENTENCE'),
(43101, 431, 'Would you be interested in discussing a partnership?', 'Bạn có muốn trao đổi về hợp tác không?', '/wʊd ju bi ˈɪntəˌrɛstɪd ɪn dɪˈskəsɪŋ ə ˈpɑrtnərˌʃɪp/', '', 'PRACTICE_SENTENCE'),
(43102, 431, 'Yes. Could you explain the campaign goals?', 'Có. Bạn giải thích mục tiêu chiến dịch nhé?', '/jɛs. kʊd ju ɪkˈspleɪn ðə kæmˈpeɪn goʊlz/', '', 'PRACTICE_SENTENCE'),
(43103, 431, 'We would like content that fits our audience.', 'Chúng tôi muốn nội dung phù hợp đối tượng khách hàng.', '/wi wʊd laɪk ˈkɑntɛnt ðət fɪts ɑr ˈɔdiəns/', '', 'PRACTICE_SENTENCE'),
(43104, 431, 'partnership', 'hợp tác', '/ˈpɑrtnərˌʃɪp/', '', 'VOCABULARY'),
(43105, 431, 'scope', 'phạm vi', '/skoʊp/', '', 'VOCABULARY'),
(43106, 431, 'revision', 'chỉnh sửa', '/riˈvɪʒən/', '', 'VOCABULARY'),
(43107, 431, 'What type of content do you have in mind?', 'Bạn dự định loại nội dung nào?', '/wət taɪp əv ˈkɑntɛnt du ju hæv ɪn maɪnd/', '', 'PRACTICE_SENTENCE'),
(43108, 431, 'Let us discuss the scope and schedule.', 'Hãy trao đổi phạm vi và lịch trình.', '/lɛt ˈjuˈɛs dɪˈskəs ðə skoʊp ənd ˈskɛʤʊl/', '', 'PRACTICE_SENTENCE'),
(43109, 431, 'Could you also explain the usage rights?', 'Bạn giải thích cả quyền sử dụng nhé?', '/kʊd ju ˈɔlsoʊ ɪkˈspleɪn ðə ˈjusɪʤ raɪts/', '', 'PRACTICE_SENTENCE'),
(43110, 431, 'We will include the agreed terms in writing.', 'Chúng tôi sẽ ghi điều khoản thống nhất bằng văn bản.', '/wi wɪl ˌɪnˈklud ðə əˈgrid tərmz ɪn ˈraɪtɪŋ/', '', 'PRACTICE_SENTENCE'),
(43111, 431, 'Thank you. I will review them before confirming.', 'Cảm ơn. Tôi sẽ xem trước khi xác nhận.', '/θæŋk ju. aɪ wɪl ˌrivˈju ðɛm ˌbiˈfɔr kənˈfərmɪŋ/', '', 'PRACTICE_SENTENCE'),
(43112, 431, 'Who will approve the final content?', 'Ai sẽ duyệt nội dung cuối cùng?', '/hu wɪl əˈpruv ðə ˈfaɪnəl ˈkɑntɛnt/', '', 'PRACTICE_SENTENCE'),
(43113, 431, 'Can we clarify the number of revisions included?', 'Chúng ta làm rõ số lần chỉnh sửa được bao gồm nhé?', '/kən wi ˈklɛrəˌfaɪ ðə ˈnəmbər əv riˈvɪʒənz ˌɪnˈkludɪd/', '', 'PRACTICE_SENTENCE'),
(43201, 432, 'Would you have a few minutes to share your feedback?', 'Bạn có vài phút để chia sẻ góp ý không?', '/wʊd ju hæv ə fju ˈmɪnəts tə ʃɛr jʊr ˈfidˌbæk/', '', 'PRACTICE_SENTENCE'),
(43202, 432, 'Yes. What would you like to know?', 'Có. Bạn muốn biết điều gì?', '/jɛs. wət wʊd ju laɪk tə noʊ/', '', 'PRACTICE_SENTENCE'),
(43203, 432, 'How was your experience with our service?', 'Trải nghiệm dịch vụ của bạn thế nào?', '/haʊ wɑz jʊr ɪkˈspɪriəns wɪθ ɑr ˈsərvɪs/', '', 'PRACTICE_SENTENCE'),
(43204, 432, 'survey', 'khảo sát', '/ˈsərˌveɪ/', '', 'VOCABULARY'),
(43205, 432, 'anonymous', 'ẩn danh', '/əˈnɑnəməs/', '', 'VOCABULARY'),
(43206, 432, 'improve', 'cải thiện', '/ˌɪmˈpruv/', '', 'VOCABULARY'),
(43207, 432, 'The staff were helpful, but the waiting time was long.', 'Nhân viên nhiệt tình nhưng thời gian chờ lâu.', '/ðə stæf wər ˈhɛlpfəl, bət ðə ˈweɪtɪŋ taɪm wɑz lɔŋ/', '', 'PRACTICE_SENTENCE'),
(43208, 432, 'What would you like us to improve?', 'Bạn muốn chúng tôi cải thiện điều gì?', '/wət wʊd ju laɪk ˈjuˈɛs tə ˌɪmˈpruv/', '', 'PRACTICE_SENTENCE'),
(43209, 432, 'It would help to provide clearer updates.', 'Sẽ hữu ích nếu cung cấp cập nhật rõ hơn.', '/ɪt wʊd hɛlp tə prəˈvaɪd ˈklɪrər ˈəpˌdeɪts/', '', 'PRACTICE_SENTENCE'),
(43210, 432, 'Thank you. Your feedback will help us review the service.', 'Cảm ơn. Góp ý sẽ giúp chúng tôi xem lại dịch vụ.', '/θæŋk ju. jʊr ˈfidˌbæk wɪl hɛlp ˈjuˈɛs ˌrivˈju ðə ˈsərvɪs/', '', 'PRACTICE_SENTENCE'),
(43211, 432, 'You are welcome. I hope it is useful.', 'Không có gì. Tôi hy vọng góp ý hữu ích.', '/ju ər ˈwɛlkəm. aɪ hoʊp ɪt ɪz ˈjusfəl/', '', 'PRACTICE_SENTENCE'),
(43212, 432, 'Is the survey anonymous?', 'Khảo sát có ẩn danh không?', '/ɪz ðə ˈsərˌveɪ əˈnɑnəməs/', '', 'PRACTICE_SENTENCE'),
(43213, 432, 'Can I skip a question if I prefer?', 'Tôi có thể bỏ qua câu hỏi nếu muốn không?', '/kən aɪ skɪp ə kˈwɛʃən ɪf aɪ prɪˈfər/', '', 'PRACTICE_SENTENCE');
INSERT INTO scenarios (scenario_id,lesson_id,title,ai_role_name,user_role_name,context_briefing,initial_ai_greeting,illustration_key,illustration_alt,partner_name,learner_name) VALUES
(551, 401, 'Báo lỗi phần mềm và mô tả cách tái hiện', 'Kỹ sư phần mềm', 'Người dùng', 'Đồng nghiệp mô tả lỗi và cung cấp các bước giúp đội IT kiểm tra.', 'What happened when you opened the page?', 'office', 'Đồng nghiệp mô tả lỗi và cung cấp các bước giúp đội IT kiểm tra.', 'Alex', 'Minh'),
(552, 402, 'Họp cập nhật tiến độ dự án IT', 'Quản lý dự án', 'Thành viên nhóm', 'Thành viên nhóm cập nhật công việc đã làm, trở ngại và bước tiếp theo.', 'What did you complete yesterday?', 'office', 'Thành viên nhóm cập nhật công việc đã làm, trở ngại và bước tiếp theo.', 'Emma', 'Lan'),
(553, 403, 'Trao đổi bảo mật và chia sẻ dữ liệu', 'Nhân viên IT', 'Nhân viên văn phòng', 'Nhân viên hỏi IT về quyền truy cập và cách gửi tài liệu an toàn.', 'Who needs access to this document?', 'office', 'Nhân viên hỏi IT về quyền truy cập và cách gửi tài liệu an toàn.', 'Taylor', 'Minh'),
(554, 404, 'Hướng dẫn đồng nghiệp dùng phần mềm mới', 'Người hướng dẫn', 'Nhân viên mới', 'Người hướng dẫn giải thích thao tác cơ bản và kiểm tra người học đã hiểu.', 'Would you like me to show you the main features?', 'office', 'Người hướng dẫn giải thích thao tác cơ bản và kiểm tra người học đã hiểu.', 'Grace', 'Lan'),
(555, 405, 'Mô tả triệu chứng trong buổi khám', 'Bác sĩ', 'Người bệnh', 'Người bệnh mô tả thời điểm xuất hiện triệu chứng cho bác sĩ.', 'What would you like to discuss today?', 'office', 'Người bệnh mô tả thời điểm xuất hiện triệu chứng cho bác sĩ.', 'Alex', 'Minh'),
(556, 406, 'Hỏi lịch xét nghiệm và hướng dẫn chuẩn bị', 'Nhân viên xét nghiệm', 'Người bệnh', 'Người bệnh hỏi nhân viên xét nghiệm về lịch và hướng dẫn chính thức.', 'Do you have a referral for the test?', 'office', 'Người bệnh hỏi nhân viên xét nghiệm về lịch và hướng dẫn chính thức.', 'Emma', 'Lan'),
(557, 407, 'Xin hồ sơ y tế và xác nhận thông tin', 'Nhân viên hồ sơ', 'Người bệnh', 'Người bệnh hỏi cách nhận bản sao hồ sơ theo quy trình của cơ sở y tế.', 'Which records would you like to request?', 'office', 'Người bệnh hỏi cách nhận bản sao hồ sơ theo quy trình của cơ sở y tế.', 'Taylor', 'Minh'),
(558, 408, 'Hỏi đường và tìm khoa trong bệnh viện', 'Nhân viên hướng dẫn', 'Khách đến khám', 'Khách hỏi quầy thông tin về vị trí khoa và khu chờ.', 'Hello. Where do you need to go?', 'office', 'Khách hỏi quầy thông tin về vị trí khoa và khu chờ.', 'Grace', 'Lan'),
(559, 409, 'Mượn sách và hỏi quy định thư viện', 'Nhân viên thư viện', 'Sinh viên', 'Sinh viên tìm sách và hỏi thời hạn mượn hoặc gia hạn.', 'Which book are you looking for?', 'office', 'Sinh viên tìm sách và hỏi thời hạn mượn hoặc gia hạn.', 'Alex', 'Minh'),
(560, 410, 'Phân chia nhiệm vụ trong dự án nhóm', 'Thành viên nhóm', 'Thành viên nhóm', 'Các thành viên nhóm thống nhất nhiệm vụ và lịch kiểm tra tiến độ.', 'Which part of the project would you like to work on?', 'office', 'Các thành viên nhóm thống nhất nhiệm vụ và lịch kiểm tra tiến độ.', 'Emma', 'Lan'),
(561, 411, 'Hỏi điều kiện và hồ sơ học bổng', 'Nhân viên tư vấn', 'Sinh viên', 'Sinh viên hỏi nhân viên trường về tiêu chí và hạn nộp học bổng.', 'Which scholarship are you interested in?', 'office', 'Sinh viên hỏi nhân viên trường về tiêu chí và hạn nộp học bổng.', 'Taylor', 'Minh'),
(562, 412, 'Nhận góp ý và cải thiện bài thuyết trình', 'Giảng viên', 'Sinh viên', 'Sinh viên trao đổi với giảng viên về điểm cần cải thiện.', 'How do you feel about your presentation?', 'office', 'Sinh viên trao đổi với giảng viên về điểm cần cải thiện.', 'Grace', 'Lan'),
