INSERT INTO scenario_turns (scenario_id,step_order,expected_user_intent,bot_reaction_rules) VALUES
(551, 1, 'The page froze after I clicked the button.', 'What happened when you opened the page?'),
(551, 2, 'First I signed in, then I opened the report.', 'Can you show me the steps you followed?'),
(551, 3, 'It happens only when I use this browser.', 'Does the problem happen every time?'),
(551, 4, 'Thank you. Please let me know when it is fixed.', 'I will record the details for our team.'),
(552, 1, 'I finished testing the new feature.', 'What did you complete yesterday?'),
(552, 2, 'I am waiting for feedback from the design team.', 'Are there any problems slowing you down?'),
